  if (history.length > 32) history.shift();
  if (status !== 200) return Response.json({ error: '教材データの読み込み失敗' }, { status });
  return Response.json({
    label: state === 'slow' ? '遅延後の晴れ' : state === 'flaky' ? '再試行後の晴れ' : '晴れ',
  });
}

